import unittest

from solucao import achar
from solucao import existe


class TestAcharNoTexto(unittest.TestCase):
    def test_acha_no_meio(self):
        """achar devolve a posicao do pedaco no meio do texto"""
        self.assertEqual(achar("banana", "na"), 2)

    def test_nao_acha_devolve_menos_um(self):
        """achar devolve -1 quando o pedaco nao existe"""
        self.assertEqual(achar("banana", "zz"), -1)

    def test_existe_quando_tem(self):
        """existe devolve True quando o pedaco esta no texto"""
        self.assertEqual(existe("banana", "na"), True)

    def test_existe_quando_nao_tem(self):
        """existe devolve False quando o pedaco nao esta no texto"""
        self.assertEqual(existe("banana", "zz"), False)

